{"drafts": [{"draft_id": "6e8ec047-17c5-5943-b45d-fa061fd8cecb", "doc_id": "1291f40b-7db3-5798-9061-f3310b3f99fe", "name": "规则冲突优先级裁决", "description": "当两条交通仿真规则看似冲突时，按作用域具体性裁决：更具体的规则覆盖更通用的规则。用于解析仿真规则冲突或未定义行为。", "asset_type": "safety_rule", "granularity": "micro", "asset_node_id": "safety_rule_node", "asset_path": "family_root/safety_module/safety_rule_node", "asset_level": 2, "visible_role": "leaf", "objective": "在规则冲突时确定唯一生效规则，避免仿真行为不确定", "domain": "交通仿真规则", "task_family": "规则冲突解析", "method_family": "作用域具体性优先", "stage": "规则执行前裁决", "applicable_signals": ["两条规则对同一对象给出不同约束", "出现未定义或冲突的仿真行为", "场景专属规则与通用规则同时适用"], "contraindications": ["规则之间无冲突", "需要新增规则而非裁决现有规则"], "intervention_moves": ["识别冲突的规则对及其作用对象", "比较两条规则的作用域具体性", "判定更具体的规则生效并覆盖更通用的规则", "记录生效规则与覆盖理由"], "workflow_steps": ["在执行仿真规则前检查是否存在规则冲突", "定位冲突规则对及其作用对象", "比较作用域具体性，判定更具体的规则优先", "明确生效规则并说明覆盖理由", "按生效规则继续执行仿真"], "triggers": ["两条规则对同一对象给出不同约束", "出现未定义或冲突的仿真行为", "场景专属规则与通用规则同时适用"], "constraints": ["仅在规则确实冲突时使用", "裁决依据为作用域具体性，不得引入未定义的新规则"], "cautions": ["若冲突无法通过作用域具体性解决，应标记为未定义行为而非强行裁决"], "output_contract": ["确定生效规则并说明覆盖理由"], "examples": [{"input": "场景专属规则对某条边设定容量，同时文档通用容量规则也适用于该边", "output": "该边的场景专属规则生效，覆盖通用容量规则，理由：作用域更具体", "notes": "单条边的场景规则优先于通用规则"}], "risk_class": "medium", "confidence": 0.85, "support_ids": ["5e387409-edc6-5a74-aa67-0ea8f6182599"], "metadata": {"prompt": "在应用仿真规则前，先检查是否存在两条规则对同一对象给出不同约束。若存在冲突，比较两条规则的作用域具体性：作用域更具体的规则优先，覆盖更通用的规则（例如针对单条边的场景专属规则覆盖文档中的通用容量规则）。裁决后明确说明哪条规则生效及覆盖理由，再继续执行仿真。", "tags": ["规则冲突", "优先级裁决", "作用域具体性", "交通仿真"], "files": {}, "resources": {}, "source_sections": ["User Questions"], "extraction_unit": "window", "domain_type": "traffic simulation rules", "taxonomy_id": "traffic simulation rules", "asset_node_id": "safety_rule_node", "asset_path": "family_root/safety_module/safety_rule_node", "asset_level": 2, "visible_role": "leaf", "candidate_slot": 1, "window_id": "63726db9-c215-572a-9ef9-b53bd8f82de9", "window_strategy": "strict", "anchor_hits": [], "paragraph_start": 26, "paragraph_end": 28, "heading_path": ["User Questions"], "parent_heading": "", "sibling_headings": ["CL-Bench: Empirical Discovery & Simulation / Simulation Environment", "System Context"], "subsection_headings": ["1. Overview", "2. Nodes and Edges", "3. Time and Update Order", "4. Vehicles", "5. Consignments (Packages)", "6. Legal Actions Per Tick", "7. Edge Capacity, Queues, and Conflicts", "8. Traffic Signals", "9. Loading and Unloading", "10. Incidents and Road Closures", "11. Priorities and Service Levels", "12. Controller Objectives", "13. Rule Conflicts and Undefined Behavior", "1. Map Overview", "2. Edges", "3. Signal Settings", "4. Vehicles in the Morning Rush Scenario", "5. Consignments", "6. Incidents", "7. Scenario Horizon and Objective", "1. State Snapshot Format", "1.1 GLOBAL Section", "1.2 NODES Section", "1.3 EDGES Section", "1.4 VEHICLES Section", "1.5 CONSIGNMENTS Section", "1.6 INCIDENTS_ACTIVE Section", "2. Worked Example A:Simple Departure", "3. Worked Example B:Signal at Central Intersection", "4. Worked Example C:Capacity Reduction Incident"], "context_snippets": [], "heading_number": "", "heading_kind": "outline_llm", "section_summary": "R1. The Arclight Freight Network (AFN) is a fictional urban road and logistics system used to simulate movement of vehicles and packages over discrete time steps."}}], "supports": [{"support_id": "5e387409-edc6-5a74-aa67-0ea8f6182599", "doc_id": "1291f40b-7db3-5798-9061-f3310b3f99fe", "section": "User Questions", "excerpt": "R49. Secondary objectives may include minimizing total distance traveled or minimizing the number of vehicles used, but these only apply when explicitly specified.

13. Rule Conflicts and Undefined Behavior

R50. If two rules appear to conflict, rules with more specific scope override more general rules. For example, a scenario-specific rule about a single edge overrides this document’s generic capacity rule for that edge.", "relation_type": "constraint", "confidence": 0.85}], "target_state": "active"}
